float fbm(vec2 _st)
{
    float v = 0.0;
    float a = 0.5;
    vec2 shift = vec2(100.0, 100.0);
    mat2 rot = mat2(cos(0.5), sin(0.5),
                    -sin(0.5), cos(0.50));

    for (int i = 0; i < NUM_OCTAVES; ++i)
