func mergePolylines(polylines: [MKPolyline]) -> [MKPolyline] {
    var coordinates: [CLLocationCoordinate2D] = []

    for polyline in polylines {
        coordinates.append(contentsOf: polyline.coordinates)
    }

    while true {
        var intersects = false

        for i in 0 ..< coordinates.count - 2 {
            let startCoordinate = coordinates[i]
            let endCoordinate = coordinates[i + 1]
            let segment = [startCoordinate, endCoordinate]

            for j in i + 2 ..< coordinates.count - 1 {
                let otherStartCoordinate = coordinates[j]
                let otherEndCoordinate = coordinates[j + 1]
                let otherSegment = [otherStartCoordinate, otherEndCoordinate]
                if let intersection = MKGeometry.lineSegmentIntersection(segment, otherSegment),
                    intersection != startCoordinate && intersection != endCoordinate {
                    intersects = true
                    coordinates.insert(intersection, at: j + 1)
                    coordinates.removeSubrange(i + 1 ... j)
                    break
                }
            }

            if intersects {
                break
            }
        }

        if !intersects {
            break
        }
    }

    var result: [MKPolyline] = []
    var currentCoordinates: [CLLocationCoordinate2D] = []

    for coordinate in coordinates {
        currentCoordinates.append(coordinate)

        if currentCoordinates.count == 2 {
            result.append(MKPolyline(coordinates: currentCoordinates, count: 2))
            currentCoordinates = []
        }
    }

    return result
}
